	"cloud.google.com/go/spanner/admin/instance/apiv1/instancepb"
	tcspanner "github.com/testcontainers/testcontainers-go/modules/gcloud/spanner"
)

func TestMain(m *testing.M) {
	cleanup, err := setupSpannerEmulator(context.Background())
	if err != nil {
		panic(fmt.Sprintf("Failed to setup Spanner emulator: %v", err))
	}

	code := m.Run()

	cleanup()

	os.Exit(code)
}

func setupSpannerEmulator(ctx context.Context) (func(), error) {
	container, err := tcspanner.Run(ctx, "gcr.io/cloud-spanner-emulator/emulator:latest")
	if err != nil {
		return nil, fmt.Errorf("Failed to run Spanner emulator container: %w", err)
	}
	os.Setenv("SPANNER_EMULATOR_HOST", fmt.Sprintf("passthrough:///%s", container.URI()))

	instanceAdminClient, err := instance.NewInstanceAdminClient(ctx)
	if err != nil {
		return nil, fmt.Errorf("Failed to create Spanner instance admin client: %w", err)
	}
	defer instanceAdminClient.Close()

	op, err := instanceAdminClient.CreateInstance(ctx, &instancepb.CreateInstanceRequest{
		Parent:     "projects/test-project",
		InstanceId: "test-instance",
		Instance: &instancepb.Instance{
			Config:      "projects/test-project/instanceConfigs/emulator-config",
			DisplayName: "test-instance",
			NodeCount:   1,
		},
	})
	if err != nil {
		return nil, fmt.Errorf("Failed to create Spanner instance: %w", err)
	}

	i, err := op.Wait(ctx)
	if err != nil {
		return nil, fmt.Errorf("Failed to wait for Spanner instance creation: %w", err)
	}

	if i.State != instancepb.Instance_READY {
		return nil, fmt.Errorf("Spanner instance is not ready: %v", i.State)
	}

	return func() {
		if err := container.Terminate(ctx); err != nil {
			panic(fmt.Sprintf("Failed to terminate Spanner emulator container: %v", err))
		}
	}, nil
}

func TestSpannerApplyFailure(t *testing.T) {
	t.Parallel()

	for i := range 300 {
		t.Run(fmt.Sprintf("Test %d", i), func(t *testing.T) {
			t.Parallel()

			ctx := t.Context()
			adminClient, err := database.NewDatabaseAdminClient(ctx)
			if err != nil {
				t.Fatalf("Failed to create Spanner database admin client: %v", err)
			}
			t.Cleanup(func() {
				if err := adminClient.Close(); err != nil {
					t.Fatalf("Failed to close Spanner database admin client: %v", err)
				}
			})

			op, err := adminClient.CreateDatabase(ctx, &databasepb.CreateDatabaseRequest{
				Parent:          "projects/test-project/instances/test-instance",
				CreateStatement: fmt.Sprintf("CREATE DATABASE `apply-failure-%03d`", i),
				ExtraStatements: []string{
					"CREATE TABLE Test (ID INT64 NOT NULL, Name STRING(MAX) NOT NULL) PRIMARY KEY(ID)",
				},
			})
			if err != nil {
				t.Fatalf("Failed to create Spanner database: %v", err)
			}

			d, err := op.Wait(ctx)
			if err != nil {
				t.Fatalf("Failed to wait for Spanner database creation: %v", err)
			}
			t.Cleanup(func() {
				if err := adminClient.DropDatabase(context.WithoutCancel(ctx), &databasepb.DropDatabaseRequest{
					Database: d.Name,
				}); err != nil {
					t.Fatalf("Failed to drop Spanner database: %v", err)
				}
			})

			client, err := spanner.NewClient(ctx, d.Name)
			if err != nil {
				t.Fatalf("Failed to create Spanner client: %v", err)
			}
			t.Cleanup(func() {
				client.Close()
			})

			if _, err := client.Apply(ctx, []*spanner.Mutation{
				spanner.Insert("Test", []string{"ID", "Name"}, []any{1, "test"}),
			}); err != nil {
				t.Fatalf("Failed to apply Spanner mutations: %v", err)
			}

			retried := 0
			for range 5 {
				if _, err := client.Single().ReadRow(ctx, "Test", spanner.Key{1}, []string{"ID", "Name"}); err != nil {
					t.Logf("Failed to read Spanner row at attempt %d: %v", retried+1, err)
					time.Sleep(10 * time.Millisecond)
					retried++
					continue
				}
				break
			}
			if retried > 0 {
				t.Errorf("Failed to read Spanner row %d times", retried)
			}
		})
	}
}

